import numpy as np
anoms = []
for L in range(24):
    for nm in ['gate_proj','up_proj']:
        W = load_original(f'model.language_model.layers.{L}.mlp.{nm}.weight').float().numpy()  # (3584, 1024)
        cn = np.linalg.norm(W, axis=0)   # input-side (1024)
        rn = np.linalg.norm(W, axis=1)   # unit-side (3584)
        if cn.min() < 1e-3 or rn.min() < 1e-3:
            print(f'L{L} {nm}: near-zero col/row min {cn.min():.2e}/{rn.min():.2e} count {np.sum(cn<1e-3)}/{np.sum(rn<1e-3)}')
        if cn.max() > 5*np.median(cn) or rn.max() > 5*np.median(rn):
